uniform float scale : 0.2 .. 4.0 = 1.0;
uniform float drift : 0.0 .. 2.0 = 0.3;

void update() {}

vec3 shade(Led led) {
  float h = fract(led.pos.y * scale + time * drift);
  return hsv2rgb(h, 0.9, 1.0);
}

uniform float rate : 0.1 .. 3.0 = 1.0;
uniform vec3 base : color = 1.0, 0.3, 0.1;
state float glow;

void update() { glow = 0.5 + 0.5 * sin(time * rate); }

vec3 shade(Led led) { return base * glow; }

uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float drift : 0.0 .. 2.0 = 0.3;

void update() {}

void update() {}\n\nvect3 shade(Led led) {\n  float h = fract(led.pos.y * speed + time * drift);\n  return hsv2rgb(h, 0.9, 1.0);\n}
  float h = fract(led.pos.y * scale + time * drift);
  return hsv2rgb(h, 0.9, 1.0);
}

uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float width : 0.02 .. 0.5 = 0.12;
uniform vec3 tint : color = 0.2, 0.6, 1.0;

void update() {
    for (int i = 0; i < seg_count(); ++i) {
        Led led = term(i);
        if (led.idx == frame % trail.size()) {
            float comet_speed = speed;
            vec3 comet_color = mix(tint, palette1(0.5), clamp(mod(frame, 20), 0, 1));
            float tail_width = smoothstep(width * 0.5, width, abs(fract(led.s - time * comet_speed) - 0.5));
            trail[i] = mix(comet_color, trail[i], tail_width);
        }
    }
}

vec3 shade(Led led) {
    float phase = fract(led.s - time * speed);
    float band = smoothstep(width, 0.0, abs(phase - 0.5));
    return tint * band;
}
